package com.sobrenaturaldirector.memory;
import java.util.*; import com.sobrenaturaldirector.derivation.*;
public final class MemoryCandidateGenerator { public static final int MAX_CANDIDATES=32; public List<MemoryCandidate> generate(ObservationDelta d,long tick){Map<String,MemoryCandidate> out=new TreeMap<String,MemoryCandidate>();for(PlayerDelta x:d.getPlayers()){String type=null;double importance=.4;RetentionClass retention=RetentionClass.SHORT_TERM;if(x.isDeath()){type="PLAYER_DEATH";importance=1;retention=RetentionClass.LONG_TERM;}else if(x.isDimensionChanged())type="DIMENSION_CHANGED";else if(x.isHealthChanged()&&x.getHealthBefore()-x.getHealthAfter()>=4)type="LOW_HEALTH_EXPOSURE";else if(x.isInventoryChanged()||x.isArmorChanged())type="INVENTORY_CHANGED";if(type!=null){String key=type+":"+x.getPlayerId();MemoryCandidate old=out.get(key);int count=old==null?1:old.getOccurrenceCount()+1;out.put(key,new MemoryCandidate("memory:"+key,type,x.getPlayerId().toString(),tick,importance,retention,Confidence.KNOWN,key,count));}}List<MemoryCandidate>r=new ArrayList<MemoryCandidate>(out.values());if(r.size()>MAX_CANDIDATES)r=new ArrayList<MemoryCandidate>(r.subList(0,MAX_CANDIDATES));return Collections.unmodifiableList(r);} }
